begin;

on conflict (entry_key) do update
set published_data = public.website_studio_entries.published_data || excluded.published_data,
    draft_data = case when public.website_studio_entries.draft_data is null then null else public.website_studio_entries.draft_data || excluded.published_data end,
    published_version = public.website_studio_entries.published_version + 1,
    published_at = now(),
    updated_at = now();

commit;
